use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored, tried in order.
const KEYS: [&str; 5] = ["subscriptions", "urls", "feeds", "list", "all"];

/// Collect every JSON string literal in `src`, decoding escapes.
fn json_strings(src: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = src.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut s = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{8}'),
                    Some('f') => s.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                    }
                    Some(other) => s.push(other),
                    None => break,
                },
                other => s.push(other),
            }
        }
        if closed {
            out.push(s);
        }
    }
    out
}

fn parse(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let mut candidates: Vec<String> = Vec::new();

    if trimmed.starts_with('[') || trimmed.starts_with('{') || trimmed.starts_with('"') {
        let strings = json_strings(trimmed);
        let with_scheme: Vec<String> = strings
            .iter()
            .filter(|s| s.contains("://"))
            .cloned()
            .collect();
        if !with_scheme.is_empty() {
            candidates = with_scheme;
        } else if !trimmed.starts_with('{') {
            candidates = strings;
        }
    } else {
        for line in trimmed.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for tok in line.split(|c: char| c == ',' || c == ';' || c.is_whitespace()) {
                candidates.push(tok.to_string());
            }
        }
    }

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                let urls = parse(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires a present (non-empty) list of urls. With no
        // subscriptions in the store there is no honest output to produce,
        // so fail rather than emit a value that violates the contract.
        panic!("no subscriptions found in state store");
    }
}

export!(Node);
